<?php require __DIR__.'/_layout_start.php'; ?><div class="toolbar"><div><h1>Utenti CAT</h1><p class="muted">Account individuali e richieste di accesso.</p></div><a class="btnlink" href="/admin/cat/users/form">Nuovo utente CAT</a></div>
<div class="quick-list" style="grid-template-columns:repeat(2,minmax(0,220px));margin-bottom:18px"><a href="/admin/cat/users"><span>Tutti</span></a><a href="/admin/cat/users?status=pending"><span>Da approvare</span></a></div>
<div class="table-wrap"><table><thead><tr><th>Utente</th><th>Contatti</th><th>Stato</th><th>Ultimo accesso</th><th>Azioni</th></tr></thead><tbody><?php foreach($users as $cat):$pending=empty($cat['active'])&&empty($cat['verified_at'])&&empty($cat['disabled_at']); ?><tr><td><strong><?= htmlspecialchars($cat['company_name'],ENT_QUOTES,'UTF-8') ?></strong><br><?= htmlspecialchars(trim($cat['contact_first_name'].' '.$cat['contact_last_name']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($cat['email'],ENT_QUOTES,'UTF-8') ?><br><span class="muted"><?= htmlspecialchars((string)$cat['phone'],ENT_QUOTES,'UTF-8') ?></span></td><td><?php if($pending): ?><span class="badge badge-warning">Da approvare</span><?php elseif(!empty($cat['active'])): ?><span class="badge badge-new">Attivo</span><?php else: ?><span class="badge">Disabilitato</span><?php endif; ?></td><td><?= !empty($cat['last_login_at'])?htmlspecialchars(date('d/m/Y H:i',strtotime((string)$cat['last_login_at'])),ENT_QUOTES,'UTF-8'):'Mai' ?></td><td><a href="/admin/cat/users/form?id=<?= (int)$cat['id'] ?>">Modifica</a><form method="post" action="/admin/cat/users/status" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int)$cat['id'] ?>"><?php if($pending): ?><button class="btn" name="action" value="approve">Approva</button><button class="btn btn-secondary" name="action" value="reject">Rifiuta</button><?php elseif(!empty($cat['active'])): ?><button class="btn btn-secondary" name="action" value="disable">Disabilita</button><?php else: ?><button class="btn" name="action" value="approve">Riattiva</button><?php endif; ?></form></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/_layout_end.php'; ?>
